package com.pipepatrol;
import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController @RequestMapping("/api") public class OperationsController {
 final PatrolController p;OperationsController(PatrolController p){this.p=p;}
 public record AccountInput(String username,String displayName,String password,Boolean enabled,String phone,String area){}
 public record Network(List<PatrolController.Node> nodes,List<PatrolController.Pipe> pipes,String source,boolean demo){}
 public record VideoInput(String url){}
 @GetMapping("/workers") public List<Map<String,Object>> workers(@RequestHeader("Authorization")String a){synchronized(p){p.admin(a);return p.db.accounts().stream().filter(x->x.role().equals("worker")).map(x->{Map<String,Object>m=new LinkedHashMap<>();m.put("username",x.username());m.put("displayName",x.displayName());m.put("enabled",x.enabled());m.put("phone",x.phone());m.put("area",x.area());var tasks=p.state.tasks.stream().filter(t->t.worker.equals(x.username())).toList();m.put("tasks",tasks.size());m.put("running",tasks.stream().filter(t->t.status.equals("running")).count());m.put("completed",tasks.stream().filter(t->Set.of("completed","reviewed").contains(t.status)).count());long seconds=0;for(var t:tasks){seconds+=t.workedSeconds;if(!t.resumedAt.isBlank())seconds+=Math.max(0,java.time.Duration.between(java.time.Instant.parse(t.resumedAt),java.time.Instant.now()).getSeconds());}m.put("workedSeconds",seconds);m.put("openAlerts",p.state.alerts.stream().filter(al->!al.ack&&tasks.stream().anyMatch(t->t.id.equals(al.task))).count());return m;}).toList();}}
 void validate(AccountInput in,boolean create){if(in.username()==null||!in.username().matches("[A-Za-z0-9_-]{3,30}")||in.username().equals("admin"))throw PatrolController.bad("账号为3—30位字母、数字、下划线或短横线");if(in.displayName()==null||in.displayName().isBlank()||in.displayName().length()>60)throw PatrolController.bad("请填写姓名，最长60字");if((create||in.password()!=null&&!in.password().isBlank())&&(in.password()==null||in.password().length()<8||in.password().length()>100))throw PatrolController.bad("密码长度8—100位");if(in.phone()!=null&&in.phone().length()>40||in.area()!=null&&in.area().length()>100)throw PatrolController.bad("联系方式或片区过长");}
 @PostMapping("/workers") public Map<String,Boolean> create(@RequestHeader("Authorization")String a,@RequestBody AccountInput in){synchronized(p){p.admin(a);validate(in,true);p.db.account(in.username(),in.displayName(),in.password(),true,in.phone(),in.area(),true);return Map.of("ok",true);}}
 @PutMapping("/workers/{name}") public Map<String,Boolean> update(@RequestHeader("Authorization")String a,@PathVariable String name,@RequestBody AccountInput in){synchronized(p){p.admin(a);validate(in,false);if(!name.equals(in.username())||p.db.accounts().stream().noneMatch(x->x.username().equals(name)&&x.role().equals("worker")))throw PatrolController.bad("账号不存在");if(Boolean.FALSE.equals(in.enabled())&&p.state.tasks.stream().anyMatch(t->t.worker.equals(name)&&t.status.equals("running")))throw PatrolController.bad("请先暂停该人员进行中的任务");p.db.account(name,in.displayName(),in.password(),!Boolean.FALSE.equals(in.enabled()),in.phone(),in.area(),false);p.sessions.entrySet().removeIf(e->e.getValue().name().equals(name));return Map.of("ok",true);}}
 @PutMapping("/network") public Map<String,Integer> network(@RequestHeader("Authorization")String a,@RequestBody Network n){synchronized(p){p.admin(a);if(n.nodes()==null||n.pipes()==null||n.nodes().size()<2||n.nodes().size()>3000||n.pipes().isEmpty()||n.pipes().size()>6000)throw PatrolController.bad("管网应含2—3000座井、1—6000条管段");Set<String>ids=new HashSet<>();for(var x:n.nodes()){if(x.id()==null||!x.id().matches("[A-Za-z0-9_-]{1,40}")||!ids.add(x.id())||x.label()==null||x.label().length()>100||Math.abs((long)x.x())>1000000||Math.abs((long)x.y())>1000000)throw PatrolController.bad("井编号、名称或坐标无效");if((x.lng()==null)!=(x.lat()==null)||x.lng()!=null&&(!Double.isFinite(x.lng())||!Double.isFinite(x.lat())||Math.abs(x.lng())>180||Math.abs(x.lat())>85))throw PatrolController.bad("经纬度无效");}Set<String>pipes=new HashSet<>();for(var x:n.pipes()){if(x.id()==null||!x.id().matches("[A-Za-z0-9_-]{1,40}")||!pipes.add(x.id())||!ids.contains(x.from())||!ids.contains(x.to())||x.from().equals(x.to())||x.length()<=0||x.length()>100000||x.diameter()<50||x.diameter()>3000||!Set.of("normal","attention","blocked").contains(x.status()))throw PatrolController.bad("管段编号、连接关系、长度或管径无效");}
 if(n.source()==null||n.source().isBlank()||n.source().length()>400)throw PatrolController.bad("请填写数据来源");
 Set<String>inUse=new HashSet<>();Set<String>usedNodes=new HashSet<>();for(var t:p.state.tasks){inUse.addAll(t.pipes);usedNodes.add(t.start);usedNodes.add(t.end);}if(!pipes.containsAll(inUse)||!ids.containsAll(usedNodes))throw PatrolController.bad("已关联任务的井或管段应保留编号；请导入同片区补充资料");
 if(p.state.tasks.stream().anyMatch(t->t.status.equals("running")))throw PatrolController.bad("存在进行中的任务，请暂停后更新管网");
 p.state.nodes=new ArrayList<>(n.nodes());p.state.pipes=new ArrayList<>(n.pipes());p.state.networkSource=n.source();p.state.demo=n.demo();p.save();return Map.of("nodes",n.nodes().size(),"pipes",n.pipes().size());}}
 @PostMapping("/messages/{id}/ack") public Map<String,Boolean> ack(@RequestHeader("Authorization")String a,@PathVariable String id){synchronized(p){var u=p.user(a);for(int i=0;i<p.state.messages.size();i++){var m=p.state.messages.get(i);if(!m.id().equals(id))continue;var t=p.task(m.task());if(!u.role().equals("admin")&&!t.worker.equals(u.name()))throw new UnsupportedOperationException("无权确认");if(m.sender().equals(u.name()))throw PatrolController.bad("请由接收方确认消息");p.state.messages.set(i,new PatrolController.Message(m.id(),m.task(),m.text(),m.at(),m.sender(),true));p.event(t,u,"message_ack","确认消息："+m.text());p.save();return Map.of("ok",true);}throw PatrolController.bad("消息不存在");}}
 @GetMapping("/tasks/{id}/telemetry") public List<Map<String,Object>> history(@RequestHeader("Authorization")String a,@PathVariable String id){synchronized(p){var u=p.user(a);if(!u.role().equals("admin")&&!p.task(id).worker.equals(u.name()))throw new UnsupportedOperationException("无权访问");return p.db.history(id);}}
 @PutMapping("/tasks/{id}/video") public Map<String,Boolean> video(@RequestHeader("Authorization")String a,@PathVariable String id,@RequestBody VideoInput v){synchronized(p){var u=p.user(a);var t=p.task(id);if(!u.role().equals("admin")&&!t.worker.equals(u.name()))throw new UnsupportedOperationException("无权设置视频");if(v.url()==null||v.url().length()>2000||!v.url().isBlank()&&!v.url().matches("^https?://[^\\s]+$"))throw PatrolController.bad("请输入http或https视频地址");t.videoUrl=v.url();p.save();return Map.of("ok",true);}}
}
